import type { A1ListeningEpisode, A1ListeningSeries, EpisodeAudit, Question } from './schema'

/**
 * Temporada 3 de la serie rusa. Dos años después de «Тетрадь студии Луна»: la obra ya
 * se estrenó y llega una carta de Ирина Морозова, la compositora de la vieja studia,
 * que reclama la mitad del texto. El caso ya no es «quién escribió esto», sino «de quién
 * es una obra escrita entre dos» y qué hace un malentendido publicado a destiempo.
 *
 * `SeriesLevel` ya incluye 'B1', así que aquí se usa `A1ListeningSeries` sin tipos locales.
 */

type Spec = [string, string, string, string, string]
const question = ([prompt, correct, wrong1, wrong2, feedback]: Spec): Question => {
  const answer = [...prompt].reduce((sum, char) => sum + char.codePointAt(0)!, 0) % 3
  const options = [wrong1, wrong2]
  options.splice(answer, 0, correct)
  return { prompt, options, answer, feedback }
}
type Draft = Omit<A1ListeningEpisode, 'ttsScript' | 'gist' | 'details' | 'consolidation' | 'audit'> & { gist: Spec; details: [Spec, Spec, Spec]; consolidation: Spec; audit: Omit<EpisodeAudit, 'level' | 'estimatedDuration' | 'grammarUsed' | 'newVocabulary'> }
const ep = (draft: Draft): A1ListeningEpisode => ({ ...draft, ttsScript: draft.turns.map((turn) => turn.target).join(' '), gist: question(draft.gist), details: draft.details.map(question) as [Question, Question, Question], consolidation: question(draft.consolidation), audit: { level: 'B1', grammarUsed: draft.grammar, newVocabulary: draft.keywords.map((word) => word.target), estimatedDuration: draft.duration, ...draft.audit } })

